import fractions

def build_instance(rng):
    start_integer = rng.randint(1, 10)
    end_integer = rng.randint(start_integer, start_integer + 10)
    area = start_integer * end_integer
    answer = str(area)
    check = str(fractions.Fraction(area))
    parameters = {'start_integer': start_integer, 'end_integer': end_integer}
    return (parameters, answer, check)



